import{_ as o,o as d,c as r,a2 as e}from"./chunks/framework.BC3NdntU.js";const u=JSON.parse('{"title":"B3 网络请求对比","description":"","frontmatter":{},"headers":[],"relativePath":"附录B-对比清单/B3-网络请求对比.md","filePath":"附录B-对比清单/B3-网络请求对比.md","lastUpdated":1788847550000}'),a={name:"附录B-对比清单/B3-网络请求对比.md"};function s(n,t,l,i,h,c){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="b3-网络请求对比" tabindex="-1">B3 网络请求对比 <a class="header-anchor" href="#b3-网络请求对比" aria-label="Permalink to &quot;B3 网络请求对比&quot;">​</a></h1><blockquote><p>附录 B · 对比清单</p></blockquote><hr><h2 id="总对比表" tabindex="-1">总对比表 <a class="header-anchor" href="#总对比表" aria-label="Permalink to &quot;总对比表&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>XHR</th><th>Fetch</th><th>axios</th><th>SSE</th><th>WebSocket</th></tr></thead><tbody><tr><td>形态</td><td>事件回调</td><td>Promise(流式)</td><td>Promise(封装)</td><td>事件流</td><td>事件</td></tr><tr><td>方向</td><td>请求-响应</td><td>请求-响应</td><td>请求-响应</td><td>服务端→客户端</td><td><strong>双向</strong></td></tr><tr><td>进度监控</td><td>✅</td><td>❌</td><td>✅(上传/下载)</td><td>—</td><td>—</td></tr><tr><td>中止</td><td><code>abort()</code></td><td>AbortController</td><td>AbortController/CancelToken</td><td>关闭</td><td>close</td></tr><tr><td>拦截器</td><td>❌</td><td>❌</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>底层</td><td>原生</td><td>原生</td><td>基于 XHR(浏览器)</td><td>HTTP 长连接</td><td>ws 协议</td></tr><tr><td>场景</td><td>老代码/需进度</td><td>轻量原生</td><td>统一配置/拦截</td><td>单向推送</td><td>实时双向</td></tr></tbody></table><hr><h2 id="关键差异-底层" tabindex="-1">关键差异(底层) <a class="header-anchor" href="#关键差异-底层" aria-label="Permalink to &quot;关键差异(底层)&quot;">​</a></h2><ul><li><strong>XHR</strong>:事件模型,能监控上传/下载进度,但 API 啰嗦、已停更</li><li><strong>Fetch</strong>:Promise + <strong>流式</strong>(收到响应头即 resolve,body 需再读),现代标准</li><li><strong>axios</strong>:在 XHR 之上封装<strong>拦截器、取消、统一配置</strong>,非原生</li><li><strong>SSE</strong>:基于 HTTP 的<strong>单向</strong>推送(<code>text/event-stream</code>),原生 <code>EventSource</code></li><li><strong>WebSocket</strong>:独立 <code>ws</code> 协议,<strong>双向</strong>长连接,先 HTTP 升级</li></ul><hr><h2 id="选型建议" tabindex="-1">选型建议 <a class="header-anchor" href="#选型建议" aria-label="Permalink to &quot;选型建议&quot;">​</a></h2><ul><li>简单请求、轻量 → <strong>Fetch</strong></li><li>要拦截器/统一 token/超时/进度 → <strong>axios</strong></li><li>服务端单向推送(行情/通知) → <strong>SSE</strong></li><li>实时双向(聊天/协作/游戏) → <strong>WebSocket</strong></li></ul><blockquote><p>一句话:<strong>Fetch 原生轻量、axios 工程化、SSE 单向推、WebSocket 双向</strong>。</p></blockquote><hr><h2 id="深入思考" tabindex="-1">深入思考 <a class="header-anchor" href="#深入思考" aria-label="Permalink to &quot;深入思考&quot;">​</a></h2><ol><li><strong>axios 为什么长期流行</strong>:不是因为它快,而是&quot;拦截器 + 统一配置 + 进度/取消&quot;的工程化能力,正好补上原生 XHR/Fetch 的短板。选 axios 是选&quot;工程化&quot;,不是选&quot;网络能力&quot;。</li><li><strong>Fetch 的价值</strong>:流式 body 适合大文件/SSE 场景,且是标准、零依赖。轻量场景优先 Fetch,避免为一个简单请求引入整个 axios。</li><li><strong>趋势</strong>:原生能力(AbortController + 流式)在补齐,axios 的&quot;必需性&quot;在下降,但拦截器/统一错误处理的便利性仍有价值。</li></ol><hr><p>📎 参考:MDN《Fetch》《EventSource》《WebSocket》、axios 文档、卷四 4.5 对应章节</p>',17)])])}const b=o(a,[["render",s]]);export{u as __pageData,b as default};
